module Anchors = struct
  let create_table db =
    U.exec db
      {|
        CREATE TABLE IF NOT EXISTS "anchors" (
          anchor_id            INTEGER PRIMARY KEY AUTOINCREMENT,
          doc_id               INTEGER NOT NULL REFERENCES documents(doc_id),
          doc_revision         INTEGER NOT NULL,
          doc_revision_attempt INTEGER NOT NULL,
          "start"              INTEGER NOT NULL,
          "end"                INTEGER NOT NULL,
          last_author          TEXT    NOT NULL,
          raw_contents         BLOB    NOT NULL,
          acknowledged_revision INTEGER
        )
      |};
    U.exec db
      {|CREATE INDEX IF NOT EXISTS "anchors_doc_id" ON "anchors" (doc_id)|};
    U.exec db
      {|CREATE INDEX IF NOT EXISTS "anchors_start" ON "anchors" ("start")|};
    U.exec db
      {|CREATE INDEX IF NOT EXISTS "anchors_end" ON "anchors" ("end")|};
    U.exec db
      {|CREATE INDEX IF NOT EXISTS "anchors_doc_id_attempt"
        ON "anchors" (doc_id, doc_revision_attempt)|}

  (* Column indices, matching this table's own column order above --
     [select_cols] below selects them in this same order. *)
  let col_anchor_id = 0
  let col_doc_id = 1
  let col_doc_revision = 2
  let col_doc_revision_attempt = 3
  let col_start = 4
  let col_end = 5
  let col_last_author = 6
  let col_raw_contents = 7
  let col_acknowledged_revision = 8

  let int_option_of_column stmt i : int option =
    match Sqlite3.column stmt i with
    | Sqlite3.Data.NULL -> None
    | Sqlite3.Data.INT n -> Some (Int64.to_int n)
    | _ ->
        ksprintf failwith
          "internal error: unexpected SQLite storage class for \
           \"anchors\".acknowledged_revision at row %d"
          i

  let param_of_int_option opt_n =
    match opt_n with
    | Some n -> U.Nullable_int64 (Some (Int64.of_int n))
    | None -> U.Nullable_int64 None

  let row_to_anchor stmt : Internal_types.anchor =
    {
      anchor_id =
        A.Anchor_id.of_int64_exn (Sqlite3.column_int64 stmt col_anchor_id);
      doc_id = A.Doc_id.of_int64_exn (Sqlite3.column_int64 stmt col_doc_id);
      doc_revision = Int64.to_int (Sqlite3.column_int64 stmt col_doc_revision);
      doc_revision_attempt =
        Int64.to_int (Sqlite3.column_int64 stmt col_doc_revision_attempt);
      range =
        {
          start = Int64.to_int (Sqlite3.column_int64 stmt col_start);
          end_ = Int64.to_int (Sqlite3.column_int64 stmt col_end);
        };
      last_author =
        author_of_string (Sqlite3.column_text stmt col_last_author);
      raw_contents = Sqlite3.column_blob stmt col_raw_contents;
      acknowledged_revision =
        int_option_of_column stmt col_acknowledged_revision;
    }

  let select_cols =
    {|anchor_id, doc_id, doc_revision, doc_revision_attempt,
      "start", "end", last_author, raw_contents, acknowledged_revision|}

  let create db (a : Internal_types.anchor) : Internal_types.anchor =
    let anchor_id =
      exec_returning_one db
        {|INSERT INTO "anchors"
            (doc_id, doc_revision, doc_revision_attempt,
             "start", "end", last_author, raw_contents,
             acknowledged_revision)
          VALUES (?, ?, ?, ?, ?, ?, ?, ?)
          RETURNING anchor_id|}
        [
          U.Int64 (A.Doc_id.to_int64 a.doc_id);
          U.Int64 (Int64.of_int a.doc_revision);
          U.Int64 (Int64.of_int a.doc_revision_attempt);
          U.Int64 (Int64.of_int a.range.start);
          U.Int64 (Int64.of_int a.range.end_);
          U.Text (Util.Text.validate_exn (author_to_string a.last_author));
          U.Blob a.raw_contents;
          param_of_int_option a.acknowledged_revision;
        ]
        ~f:(fun stmt ->
          A.Anchor_id.of_int64_exn (Sqlite3.column_int64 stmt 0))
    in
    { a with Internal_types.anchor_id }

  let get db (anchor_id : T.anchor_id) : Internal_types.anchor option =
    U.query_rows db
      (sprintf {|SELECT %s FROM "anchors" WHERE anchor_id = ?|} select_cols)
      [ U.Int64 (A.Anchor_id.to_int64 anchor_id) ]
      ~f:row_to_anchor
    |> function
    | [] -> None
    | x :: _ -> Some x

  let delete db (anchor_id : T.anchor_id) =
    U.exec_params db {|DELETE FROM "anchors" WHERE anchor_id = ?|}
      [ U.Int64 (A.Anchor_id.to_int64 anchor_id) ]

  let relocate db (a : Internal_types.anchor) =
    U.exec_params db
      {|UPDATE "anchors"
        SET doc_id = ?, doc_revision = ?, doc_revision_attempt = ?,
            "start" = ?, "end" = ?, last_author = ?, raw_contents = ?
        WHERE anchor_id = ?|}
      [
        U.Int64 (A.Doc_id.to_int64 a.doc_id);
        U.Int64 (Int64.of_int a.doc_revision);
        U.Int64 (Int64.of_int a.doc_revision_attempt);
        U.Int64 (Int64.of_int a.range.start);
        U.Int64 (Int64.of_int a.range.end_);
        U.Text (Util.Text.validate_exn (author_to_string a.last_author));
        U.Blob a.raw_contents;
        U.Int64 (A.Anchor_id.to_int64 a.anchor_id);
      ]

  let mark_attempt_failed db (anchor_id : T.anchor_id) ~doc_revision_attempt =
    U.exec_params db
      {|UPDATE "anchors" SET doc_revision_attempt = ? WHERE anchor_id = ?|}
      [
        U.Int64 (Int64.of_int doc_revision_attempt);
        U.Int64 (A.Anchor_id.to_int64 anchor_id);
      ]

  let acknowledge db (anchor_id : T.anchor_id) ~revision =
    U.exec_params db
      {|UPDATE "anchors" SET acknowledged_revision = ? WHERE anchor_id = ?|}
      [
        U.Int64 (Int64.of_int revision);
        U.Int64 (A.Anchor_id.to_int64 anchor_id);
      ]

  let get_overlapping db (doc_id : T.doc_id) ~start ~end_ :
      Internal_types.anchor list =
    U.query_rows db
      (sprintf
         {|SELECT %s FROM "anchors"
           WHERE doc_id = ? AND "start" < ? AND "end" > ?|}
         select_cols)
      [
        U.Int64 (A.Doc_id.to_int64 doc_id);
        U.Int64 (Int64.of_int end_);
        U.Int64 (Int64.of_int start);
      ]
      ~f:row_to_anchor

  let get_stale db (doc_id : T.doc_id) ~doc_revision :
      Internal_types.anchor list =
    U.query_rows db
      (sprintf
         {|SELECT %s FROM "anchors"
           WHERE doc_id = ? AND doc_revision_attempt < ?|}
         select_cols)
      [
        U.Int64 (A.Doc_id.to_int64 doc_id);
        U.Int64 (Int64.of_int doc_revision);
      ]
      ~f:row_to_anchor

  let get_all db : Internal_types.anchor list =
    U.query_rows db
      (sprintf {|SELECT %s FROM "anchors"|} select_cols)
      [] ~f:row_to_anchor

  let get_all_current db : Internal_types.anchor list =
    U.query_rows db
      (sprintf
         {|SELECT %s FROM "anchors"
           WHERE doc_revision = doc_revision_attempt|}
         select_cols)
      [] ~f:row_to_anchor

  let get_all_stale db : Internal_types.anchor list =
    U.query_rows db
      (sprintf
         {|SELECT %s FROM "anchors"
           WHERE doc_revision < doc_revision_attempt|}
         select_cols)
      [] ~f:row_to_anchor
end
(** Index documents, track anchors across edits, and search document contents.
*)

module T = App_types.Text

val create_tables : Sqlite_util.Connect.t -> unit

(* Use [App_types.Anchor_id] and [App_types.Doc_id] to convert IDs to and
    from strings such as ["anchor-123"] and ["doc-123"]. *)

type doc_meta = T.doc_meta = {
  doc_id : T.doc_id;  (** Stable across edits, deletion, and revival. *)
  source_doc : T.source_doc;  (** Source and locator used when indexing. *)
  revision : int;
      (** Increases when contents change, including deletion and revival.
          Reindexing unchanged contents preserves the revision. *)
  content_hash : string option;
      (** Opaque content digest, or [None] for a soft-deleted document. Empty
          contents have a digest. *)
}
(** A document's identity and content revision. *)

(** How to identify an indexed document. *)
type doc_ref =
  | By_locator of App_types.Src_doc.t  (** Identify by source and locator. *)
  | By_id of T.doc_id  (** Identify by stable document ID. *)

val get_all_documents : Sqlite_util.Connect.t -> doc_meta list
(** Return metadata for all documents that have not been soft-deleted. *)

val get_document_meta :
  Sqlite_util.Connect.t -> App_types.Src_doc.t -> doc_meta option
(** Return the document's metadata without its contents.

    Return [None] if the document was never indexed or has been soft-deleted.
    Use [content_hash] and [revision] to check for content changes. *)

val document_ever_indexed :
  Sqlite_util.Connect.t -> App_types.Src_doc.t -> bool
(** Test whether the document has ever been indexed, including soft-deleted
    documents.

    Use this to distinguish creation from an update or revival. Revision zero
    alone does not distinguish them: an unchanged document stays at zero. *)

val get_document :
  Sqlite_util.Connect.t -> doc_ref -> doc_meta * Util.Text_source.t
(** Return a document's metadata and stored contents without reading the
    filesystem. The contents can be used with [Slice.select_from_source].

    Raise [Failure] if the document was never indexed or has been
    soft-deleted. *)

(** Whether an anchor's range is valid in the current indexed document. *)
type anchor_status =
  | Up_to_date of Util.Text_source.t
      (** The range is current. The payload contains the indexed document's
          contents for rendering context without reading the filesystem. *)
  | Outdated
      (** The current position is unknown. The stored range and contents
          describe the last confirmed position.

          Display [anchor.raw_contents] as stale text without deriving context
          from the current document. *)

type anchor = {
  anchor_id : T.anchor_id;
  doc_id : T.doc_id;  (** Stable ID of the owning document. *)
  source_doc : T.source_doc;
      (** Source and locator of the owning document. *)
  range : T.range;
  raw_contents : string;
      (** Contents at the last confirmed range, exactly
          [range.end_ - range.start] bytes long.

          The bytes may contain invalid UTF-8. Sanitize them with
          [Util.Text.create] before display. *)
  last_author : T.author;
  status : anchor_status;
  needs_review : bool;
      (** Whether this stale anchor needs review. Acknowledging it at the
          current document revision clears this flag until the next document
          change. *)
}
(** A persistent reference to a region of an indexed document. *)

module Anchor : sig
  module Set : Set.S with type elt = anchor
end

(** {2 Sources}

    Declare each source with {!put_source} before indexing its documents.
    There is no implicit source. *)

val source_folder : App_types.Text.source -> Fpath.t
