    Raise [Failure] if the source is undeclared or still owns any documents,
    including soft-deleted documents. *)

val source_exists : Sqlite_util.Connect.t -> App_types.Text.source -> bool

val ensure_source_declared :
  Sqlite_util.Connect.t -> App_types.Text.source -> unit
(** Raise [Failure] unless the source is declared.

    Use this to validate a source before discovering or indexing its files. *)

val list_sources : Sqlite_util.Connect.t -> App_types.Text.source list
